//! 🧪️ Actual native shared construction retains null-attempt and original receipt refusals together.
use super::*;
use semio_framework_value_native_decoding::NativeAllocationEvent;
use std::sync::atomic::{AtomicUsize,Ordering};
struct Allocation{source:Arc<OriginalSourceTurnIssuer>,admitted:Arc<AtomicUsize>,posted:Arc<AtomicUsize>}
impl NativeAllocationAuthorityPort for Allocation{
 type Context<'turn,'source>=&'turn OriginalSourceTurn where 'source:'turn;
 fn validate_context<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Result<(),ValueError>where 'source:'turn{self.source.validate(c).map_err(Into::into)}
 fn source_turn<'turn,'source>(&self,c:&Self::Context<'turn,'source>)->Option<OriginalSourceTurnIdentity>where 'source:'turn{Some(c.identity())}
 fn receive<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,event:NativeAllocationEvent,reply:NativeAllocationReply<'reply>)->Result<NativeAllocationReplyComplete<'reply>,ValueError>where 'source:'turn{match event{NativeAllocationEvent::Admit(_)=>panic!("constructor uses its actual physical quote"),NativeAllocationEvent::Quote(request)=>assert_eq!(request.owned_bytes,self.admitted.load(Ordering::Relaxed)),NativeAllocationEvent::Post{request,actual}=>{self.admitted.store(request.next_owned_bytes,Ordering::Relaxed);self.posted.fetch_add(actual,Ordering::Relaxed);},NativeAllocationEvent::Cancel(_)=>{}}Ok(reply.complete(Ok(())))}
 fn recover<'reply,'turn,'source>(&mut self,_:&mut Self::Context<'turn,'source>,_:NativeAllocationEvent,reply:NativeAllocationReply<'reply>)->Result<NativeAllocationReplyComplete<'reply>,ValueError>where 'source:'turn{Ok(reply.pending())}
}
fn release_original_receipt(bank:&mut Bank,native:&mut NativeDecodeControl<'_>,receiving:&mut semio_framework_value_native_decoding::OriginalReceivingPrimary){bank.wallet.lock().unwrap().reject=false;let mut release=receipt_payout::ReceiptRelease::new(receiving);assert!(release.settle(bank,native).unwrap());drop(release);bank.wallet.lock().unwrap().reject=true}
#[test]fn actual_native_construction_keeps_null_input_and_born_output_with_both_refusals(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let stock=&row["stock"];let mut bank=Bank::from_stock(stock,false);let turn=bank.turn.clone();let admitted=Arc::new(AtomicUsize::new(0));let posted=Arc::new(AtomicUsize::new(0));let mut allocation=NativeAllocationAuthority::new(Allocation{source:bank.source.clone(),admitted:admitted.clone(),posted:posted.clone()});let mut context=turn.as_ref();let mut input=Some(row["value"].as_str().unwrap().to_owned());let pointer=input.as_ref().unwrap().as_ptr();let input_capacity=input.as_ref().unwrap().capacity();let mut slots=Slots::<SealedMode,String>::default();let mut frame=NativeReceivingEffect::default();let mut producer=OriginalEffectAuthority::new(Commands::<SealedMode,String>{source:bank.source.clone(),mode:PhantomData});
 allocation.with_send_loan(&mut context,|allocation|{
  let mut callback=|_|true;let mut native=NativeDecodeControl::new_forwarded(stock["capacityBytes"].as_u64().unwrap()as usize,&mut callback,allocation);let d=Slots::<SealedMode,String>::capture_demand().unwrap();let work=slots.capture_work_demand(&input).unwrap();complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,work,Command::Capture(&mut slots,&mut input))).result.unwrap();assert!(input.is_none());let birth_demand=SealedMode::demand(&slots).unwrap();bank.wallet.lock().unwrap().deny=true;
  assert_eq!(bank.run(&mut native,|native|SealedMode::advance(&mut slots,native)).unwrap(),NativeReceivingEffectState::Ready{work:0});assert!(slots.advance_result_ready());assert!(!slots.output_ready());assert_eq!(slots.input().unwrap().as_ptr(),pointer);assert_eq!(admitted.load(Ordering::Relaxed),0);let mut denied=None;let result_demand=slots.advance_result_demand().unwrap();let transfer_denied=complete(command(&mut bank,&mut native,&mut frame,&mut producer,result_demand,1,Command::AdvanceResult(&mut slots,&mut denied)));assert_eq!(transfer_denied.result.unwrap(),RetainedCloneStep::Progress(Default::default()));assert!(denied.is_none());assert!(slots.advance_result_ready());bank.wallet.lock().unwrap().deny=false;complete(command(&mut bank,&mut native,&mut frame,&mut producer,result_demand,1,Command::AdvanceResult(&mut slots,&mut denied))).result.unwrap();let denied=denied.take().expect("same denied original result is handed back under its funded action");assert!(!slots.advance_result_ready());assert_eq!(denied.work,u128::from(row["deniedWork"].as_u64().unwrap()));assert_eq!(denied.result.unwrap().progress(),Default::default());assert_eq!(slots.input().unwrap().as_ptr(),pointer);assert!(!slots.output_ready());assert_eq!(admitted.load(Ordering::Relaxed),0);
  {let mut wallet=bank.wallet.lock().unwrap();wallet.deny=false;wallet.reject=true;}
  let((null,attempts),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||advance_paid_rejected(&mut bank,&mut native,&mut frame,&mut producer,&mut slots,&row["receiptRetry"])));
  assert_eq!(attempts,1);let mut null=null;assert!(null.transfer.result.is_err());release_original_receipt(&mut bank,&mut native,&mut null.transfer.result.as_mut().unwrap_err().receiving);let null_work=null.observed_work();let null=null.outcome;assert_eq!(heap,(0,0));assert_eq!(null_work,u128::from(row["nullWork"].as_u64().unwrap()));let mut failure=null.result.unwrap_err();assert_eq!(failure.child.as_ref().unwrap().primary().unwrap().kind,ValueRefusalKind::AllocationFailed);assert!(failure.receiving.receipt_completion().is_some());assert_eq!(failure.retained_progress(),RetainedCloneProgress{copied_items:row["nullProgress"]["items"].as_u64().unwrap()as usize,copied_bytes:row["nullProgress"]["copyWords"].as_u64().unwrap()as usize*size_of::<usize>(),retained_capacity_bytes:row["nullProgress"]["capacityBytes"].as_u64().unwrap()as usize,released_bytes:row["nullProgress"]["releaseBytes"].as_u64().unwrap()as usize,..Default::default()});assert_eq!(failure.retained_progress().copied_bytes,size_of::<Option<usize>>());assert_eq!(slots.input().unwrap().as_ptr(),pointer);assert!(!slots.output_ready());assert_eq!(row["nullAdmission"],"requestedExtent");assert_eq!(native.owned_bytes(),birth_demand.capacity_bytes);assert_eq!(admitted.load(Ordering::Relaxed),birth_demand.capacity_bytes);assert_eq!(posted.load(Ordering::Relaxed),row["nullPhysicalBytes"].as_u64().unwrap()as usize);release_original_receipt(&mut bank,&mut native,&mut failure.receiving);
  let(born,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||advance_paid_rejected(&mut bank,&mut native,&mut frame,&mut producer,&mut slots,&row["receiptRetry"]));let mut born=born;assert!(born.transfer.result.is_err());release_original_receipt(&mut bank,&mut native,&mut born.transfer.result.as_mut().unwrap_err().receiving);let born_work=born.observed_work();let born=born.outcome;assert_eq!(born_work,u128::from(row["allocationWork"].as_u64().unwrap()));let mut failure=born.result.unwrap_err();assert!(failure.child.is_none());assert!(failure.receiving.receipt_completion().is_some());let progress=failure.retained_progress();assert_eq!(row["copiedBytes"],"quotedNativeHeader");assert_eq!(progress.copied_bytes,birth_demand.copy_bytes);assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));assert!(progress.retained_capacity_bytes>0);assert_eq!(slots.input().unwrap().as_ptr(),pointer);assert!(!slots.output_ready());release_original_receipt(&mut bank,&mut native,&mut failure.receiving);bank.wallet.lock().unwrap().reject=false;
  let(published,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||advance_paid(&mut bank,&mut native,&mut frame,&mut producer,&mut slots));let published_work=published.observed_work();let published=published.successful();published.result.unwrap();assert_eq!(published_work,u128::from(row["publicationWork"].as_u64().unwrap()));assert_eq!(heap,(0,0));assert!(!slots.output_ready());assert!(slots.input().is_none());
  let(cleared,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||advance_paid(&mut bank,&mut native,&mut frame,&mut producer,&mut slots));let cleared_work=cleared.observed_work();let cleared=cleared.successful();cleared.result.unwrap();assert_eq!(cleared_work,u128::from(row["clearBirthWork"].as_u64().unwrap()));assert_eq!(heap,(0,0));assert!(slots.output_ready());let mut output=None;let d=SealedMode::take_demand(&slots).unwrap();complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,1,Command::Take(&mut slots,&mut output))).result.unwrap();assert_eq!(output.as_ref().unwrap().get().as_ptr(),pointer);assert_eq!(serde_json::to_value(output.as_ref().unwrap().get()).unwrap(),row["value"]);
  for _ in 0..4{if slots.terminal_is_empty(){break}let d=slots.close_demand(4096).unwrap();let work=slots.close_work_demand(4096).unwrap();complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,work,Command::Close(&mut slots))).result.unwrap();}assert!(slots.terminal_is_empty());let(mut owner,mut returned)=(None,None);for _ in 0..8{if output.is_none()&&owner.is_none(){break}let(d,work)=SealedMode::consume_demand(&output,&owner).unwrap();complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,work,Command::Consume(&mut output,&mut owner,&mut returned))).result.unwrap();}assert_eq!(returned.as_ref().unwrap().as_ptr(),pointer);let d=string_release_demand(&returned).unwrap();let(_,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||complete(command(&mut bank,&mut native,&mut frame,&mut producer,d,1,Command::ReleaseString(&mut returned))).result.unwrap());assert_eq!(heap,(0,input_capacity));assert!(returned.is_none());let wallet=bank.wallet.lock().unwrap();assert_eq!(wallet.spent.released_bytes,wallet.spent.retained_capacity_bytes+input_capacity);assert_eq!(u128::from(stock["fuel"].as_u64().unwrap())-wallet.fuel,native.actual_work());assert!(native.actual_work()>0);
 }).unwrap();assert!(producer.into_producer().is_ok());assert!(allocation.into_port().is_ok());
}